'''def _run_linprog(c, A_ub=None, b_ub=None, A_eq=None, b_eq=None, bounds=None):
    """Run HiGHS through scipy, trying alternative methods on failure.

    Tight feasibility tolerances keep the rebuilt primal comfortably inside the
    verifier tolerances; if that makes the solver give up the default
    tolerances are used as a fallback.
    """
    for options in (SOLVER_OPTIONS, None):
        for method in ("highs", "highs-ds", "highs-ipm"):
            try:
                res = linprog(c, A_ub=A_ub, b_ub=b_ub, A_eq=A_eq, b_eq=b_eq,
                              bounds=bounds, method=method, options=options)
            except Exception:
                continue
            if res.status == 0 or res.status == 2:
                return res
            # status 3 (unbounded) cannot happen for this model
    return None''')
